pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != c.owner());
        vm.prank(caller);
        try c.owned() {
            revert("should have reverted");
        } catch {
            assertTrue(true);
        }
    }
}
